def handle_create_user(body):
    # Check if body is a dict
    if not isinstance(body, dict):
        return (400, {"errors": {"body": "must be an object"}})

    errors = {}
    name = None
    age = None
    email = None

    # Validate name
    if "name" not in body:
        errors["name"] = "required"
    else:
        val = body["name"]
        if not isinstance(val, str):
            errors["name"] = "must be a string"
        else:
            stripped = val.strip()
            if not stripped:
                errors["name"] = "must be non-empty"
            else:
                name = stripped

    # Validate age
    if "age" not in body:
        errors["age"] = "required"
    else:
        val = body["age"]
        # bool is a subclass of int, so we must explicitly reject bools
        if isinstance(val, bool) or not isinstance(val, int):
            errors["age"] = "must be an integer"
        elif val < 0 or val > 150:
            errors["age"] = "must be between 0 and 150"
        else:
            age = val

    # Validate email (optional)
    if "email" in body:
        val = body["email"]
        if not isinstance(val, str):
            errors["email"] = "must be a string"
        else:
            if val.count('@') != 1:
                errors["email"] = "must contain exactly one '@'"
            else:
                local, domain = val.split('@')
                if not local or not domain:
                    errors["email"] = "parts before and after '@' must be non-empty"
                else:
                    email = val

    if errors:
        return (422, {"errors": errors})

    return (201, {"name": name, "age": age, "email": email})
