import time

class Cache:
    def __init__(self, clock=time.monotonic):
        self._clock = clock
        self._data = {}

    def set(self, key, value, ttl=None):
        if ttl is not None:
            expire_at = self._clock() + ttl
            self._data[key] = (value, expire_at)
        else:
            self._data[key] = (value, None)

    def get(self, key, default=None):
        entry = self._data.get(key)
        if entry is None:
            return default
        value, expire_at = entry
        if expire_at is not None and self._clock() >= expire_at:
            del self._data[key]
            return default
        return value

    def __len__(self):
        now = self._clock()
        expired_keys = [k for k, (v, expire_at) in self._data.items() if expire_at is not None and now >= expire_at]
        for k in expired_keys:
            del self._data[k]
        return len(self._data)
