def flatten(x):
    out = []
    stack = [iter(x)]
    while stack:
        try:
            item = next(stack[-1])
            if isinstance(item, list):
                stack.append(iter(item))
            else:
                out.append(item)
        except StopIteration:
            stack.pop()
    return out
